import com.alibaba.excel.enums.CellDataTypeEnum;
import com.alibaba.excel.metadata.GlobalConfiguration;
import com.alibaba.excel.metadata.data.WriteCellData;
import com.alibaba.excel.metadata.property.ExcelContentProperty;
import jodd.util.StringUtil;
import org.apache.commons.lang3.StringUtils;

import java.lang.reflect.Field;

/**
 * easyexcel关于导出的字典值转换
 */
public class ExcelDictConverter implements Converter<Integer> {

    private String[] dictCodIsYesNoArr = {"maritalStatus", ""};

    @Override
    public Class supportJavaTypeKey() {
        return Integer.class;
    }

    @Override
    public CellDataTypeEnum supportExcelTypeKey() {
        return CellDataTypeEnum.STRING;
    }

    @Override
    public WriteCellData<?> convertToExcelData(Integer dictKey, ExcelContentProperty excelContentProperty, GlobalConfiguration globalConfiguration) throws Exception {
        // 类里需要转换的字段
        Field field = excelContentProperty.getField();
        String fieldName = field.getName();
        String excelValue = "未知";
        // 字典值为yes_no的字段
        if (StringUtils.equalsAnyIgnoreCase(fieldName, dictCodIsYesNoArr)) {
            if (dictKey == 1) {
                excelValue = "未婚";
            } else if (dictKey == 2) {
                excelValue = "离异";
            } else if (dictKey == 3) {
                excelValue = "丧偶";
            } else {
                excelValue = "未知";
            }
        }
        WriteCellData cellData = new WriteCellData();
        cellData.setData(StringUtil.isBlank(excelValue) ? dictKey.toString() : excelValue);
        return cellData;
    }
}
